from collections import deque
# Multi-source distances through 7, sources 8 and 9; direct orthogonal adjacency sources
D={8:np.full(arr.shape,999),9:np.full(arr.shape,999)}
for col in (8,9):
 q=deque()
 for r,c in zip(*np.where(arr==7)):
  if any(0<=rr<20 and 0<=cc<20 and arr[rr,cc]==col for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]):
   D[col][r,c]=1;q.append((r,c))
 while q:
  r,c=q.popleft()
  for rr,cc in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
   if 0<=rr<20 and 0<=cc<20 and arr[rr,cc]==7 and D[col][rr,cc]>D[col][r,c]+1:
    D[col][rr,cc]=D[col][r,c]+1;q.append((rr,cc))
resv=arr.copy()
for r,c in zip(*np.where(arr==7)):
 d8,d9=D[8][r,c],D[9][r,c]
 if d8<d9: resv[r,c]=8
 elif d9<d8: resv[r,c]=9
print('remaining7',len(np.argwhere(resv==7)), '9 recolors',len(np.argwhere((arr==7)&(resv==9))))
print('\n'.join('['+', '.join(map(str,row))+'],' for row in resv.tolist()))

